export const promoteStudentToInfoOfficer = async (userId: string): Promise<boolean> => {
  try {
    // Check if user already has a role
    const { data: existingRole, error: checkError } = await supabase
      .from("user_roles")
      .select("*")
      .eq("user_id", userId)
      .maybeSingle();
    
    if (checkError) throw checkError;
    
    if (existingRole) {
      // Update existing role
      const { error } = await supabase
        .from("user_roles")
        .update({ role: "information_officer" })
        .eq("user_id", userId);
      
      if (error) throw error;
    } else {
      // Insert new role
      const { error } = await supabase
        .from("user_roles")
        .insert({ user_id: userId, role: "information_officer" });
      
      if (error) throw error;
    }
    
    return true;
  } catch (error) {
    console.error("Error promoting student to information officer:", error);
    return false;
  }
};

// Other utility functions
export const createEventReminderNotifications = async (eventId: string, message: string): Promise<boolean> => {
  try {
    // Get all users interested in this event
    const { data: interested, error: interestedError } = await supabase
      .from("event_interested")
      .select("user_id")
      .eq("event_id", eventId);
    
    if (interestedError) throw interestedError;
    
    if (!interested || interested.length === 0) return true;
    
    // Get event details
    const { data: event, error: eventError } = await supabase
      .from("events")
      .select("title")
      .eq("id", eventId)
      .single();
    
    if (eventError) throw eventError;
    
    // Create notifications for all interested users
    const notifications = interested.map(item => ({
      user_id: item.user_id,
      title: `Reminder: ${event.title}`,
      message: message,
      type: "event_reminder",
      related_id: eventId,
      read: false
    }));
    
    const { error: notifError } = await supabase
      .from("notifications")
      .insert(notifications);
    
    if (notifError) throw notifError;
    
    return true;
  } catch (error) {
    console.error("Error creating event reminder notifications:", error);
    return false;
  }
};

